import{_ as e,c as l,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地風升","description":"周易折中 - 地風升","frontmatter":{"title":"地風升","description":"周易折中 - 地風升"},"headers":[],"relativePath":"classics/zhezhong/052.md","filePath":"classics/zhezhong/052.md"}'),i={name:"classics/zhezhong/052.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[h('<h1 id="地風升" tabindex="-1">地風升 <a class="header-anchor" href="#地風升" aria-label="Permalink to “地風升”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈升〉：“序卦萃者，聚也。聚而上者謂之升，故受之以《升》。物之積聚而益高大，聚而上也，故為《升》。所以次於《萃》也。為卦坤上巽下，木在地下，為地中生木，木生地中，長而益高，為《升》之象也。”</p><p>升：元亨，用見大人，勿恤，南征吉</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>升進而上也。卦自解來，柔上居四，內異外順，九二剛中而五應之，是以其佔如此。南征，前進也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>升者，進而上也。升進則有亨義，而以卦才之善，故元亨也。用此道以見大人，不假憂恤，前進則吉也。南征，前進也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>代氏淵曰 ：尊爻無此人，故不雲“利見”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>卦直言“元亨”而無他辭者，大有、鼎也。雖有他辭而非戒辭者，升也。歷選易卦，惟此三者。蓋大有與比相似，然所比者陰也、民也；所有者陽也、賢也。鼎與井相似，然往來井井者民也，大烹以養者賢也。升與漸相似，然漸者賢之有所需待而進者也，升者賢之無所阻礙而登者也。易道莫大於尚賢，而賢人得時之卦莫盛於此三者，故其彖皆曰“元亨”而無戒辭也。不曰“利見大人”而曰“用見”，代氏之說得之。</p><p>象曰：地中生木升，君子以順德，積小以高大</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>（王肅本順作愼，今案他書引此亦多作愼，意尤明白。蓋古字通用也。說見上篇䊉卦。）</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>木生地中，長而上升，為升之象。君子觀升之象，以順脩其德，積累微小以至高大也。順則可進，逆乃退也。萬物之進皆以順道也。善不積不足以成名，學業之充實，道德之崇高，皆由積累而至。積小所以成高大，升之義也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：木之生也，一日不長則枯；德之進也，一息不愼則退。必念念謹審，事事謹審，其德積小高大，當如木之升矣。</li></ul><p>彖曰：柔以時升</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦變釋卦名。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：升之為義，自下升高，故就六五居尊以釋名升之義。</p></li><li><p>徐氏幾曰 ：升、晉二卦皆以柔為主，剛則有躁進之意。</p></li><li><p>龔氏煥曰 ：彖傳“柔以時升”似指六五而言，非謂卦變。故下文言“剛中而應”，亦謂二應五也。</p></li></ul><p>巽而順，剛中而應，是以大亨</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦德、卦體釋卦辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>以二體言，柔升謂坤上行也。巽既體卑而就下，坤乃順時而上升。以時，謂時當升也。柔既上而成升，則下巽而上順，以巽順之道升，可謂時矣。二以剛中之道應於五，五以中順之德應於二。能巽而順，其升以時，是以元亨也。彖文誤作大亨，解在大有卦。</p><p>用見大人，勿恤，有慶也；南征吉，志行也</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>凡升之道，必由大人。升於位，則由王公；升於道，則由聖賢。用巽順剛中之道以見大人，必遂其升，勿恤（不憂其不遂也）。遂其升，則己之福慶而福慶及物也。南人之所向，南征謂前進也。前進則遂其升，而得行其志，是以吉也。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>柔以時升之義，或主四言，或主五言，或主上體之坤而言。然卦之有六四、六五及坤居上體者多矣，皆得名為升乎？則其說似皆未確。蓋時升者，固以坤居上體而四五得位言也。然惟巽為下體，故其升也有根。蓋巽乃陰生之始也，陰自下生，以極於上，如木之自根而滋生，以至於枝葉繁盛，此謂升之義矣。此卦與無妄反對，無妄者陽為主於內也，而其究為健；升者陰為主於內也，而其究為順。無妄之彖曰“剛自外來而為主於內”，明剛德自內以達於外也；升彖曰“柔以時升”，明陰道自下以達於上也。然則“柔以時升”雲者，尤當以初六之義為重。故無妄六爻獨初九曰吉，此卦六爻亦惟初六曰大吉。則二卦之所重者可知矣。其下雲“巽而順，剛中而應”，亦與無妄“動而健，剛中而應”之辭相似，皆連釋名之義以釋元亨也。</p><p>初六：允升，大吉</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>初以柔順居下，巽之主也。當升之時，巽於二陽，佔者如之，則信能升而大吉矣。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>初以柔居巽體之下，又巽之主，上承於九二之剛，巽之至者也。二以剛中之徳，上應於君，當升之任者也。允者，信從也。初之柔巽，唯信從於二，信二而從之，同升乃大吉也。二以徳言則剛中，以力言則當任。初之陰柔又無應援，不能自升，從於剛中之賢以進，是由剛中之道也。吉孰大焉。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏申子曰 ：以柔而升，升之義也。初以柔居下，即木之升言之，乃木之根，故信其升之必達而獲大吉也。</p></li><li><p>何氏楷曰 ：初六巽主居下，猶木之根也，而得地氣以滋之，其升也允矣。所以為升者巽也，所以為巽者初也。大吉孰如之？案此允升，允字當與晉之眾允同義，蓋不獲上信友，不可以升進也。然晉三言眾允，升初遂言允升，則王氏、何氏巽主木根之說是也。</p></li></ul><p>象曰：允升大吉，上合志也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>與在上者合志同升也。上謂九二，從二而升，乃與二同志也。能信從剛中之賢，所以大吉。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>呂氏大臨曰：初六以柔居下，當升之時，柔進而上，雖處至下，志與三陰同升，眾之所允，無所不利，故曰允升大吉。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>呂氏以上為上體三陰者是。</p><p>九二：孚乃利用禴，無咎</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>義見萃卦。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二陽剛而在下，五陰柔而居上。夫以剛而事柔，以陽而從陰，雖有時而然，非順道也。以暗而臨明，以剛而事弱，若黽勉於事勢，非誠服也。上下之交不以誠，其可以久乎？其可以有為乎？五雖陰柔然居尊位，二雖剛陽事上者也。當內存至誠，不假文飾於外。誠積於中，則自不事外飾。故曰利用禴，謂尚誠敬也。自古剛強之臣事柔弱之君，未有不為矯飾者也。禴祭之簡質者也，雲孚乃謂既孚乃宜，不用文飾，專以其誠感通於上也。如是則得無咎。以剛強之臣而事柔弱之君，又當升之時，非誠意相交，其能免於咎乎？</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>張氏清子曰 ：萃六二以中虛為孚，而與九五應；升九二以中實為孚，而與六五應。二爻虛實雖殊，其孚則一也。孚則雖用禴而亦利，故二爻皆曰“孚乃利用禴”。《彖》言“剛中而應”，指此爻也。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>升、晉之時，以柔為善。二剛而亦利者，以其中也。剛中有應，是見大人者也，故亦為升之利。初言吉，以君子得時之遇言也；二言無咎，以君子進身之道言也；六四則兼之。</p><p>象曰：九二之孚，有喜也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>二能以孚誠事上，則不唯為臣之道無咎而已，可以行剛中之道，澤及天下，是有喜也。凡象言有慶者，如是則有福慶及於物也；言有喜者，事既善而又有可喜也。如大畜童牛之梏元吉，象雲有喜，蓋梏於童則易，又免強制之難，是有可喜也。</p><p>九三：升虛邑</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>陽實陰虛，而坤有國邑之象。九三以陽剛當升時而進臨於坤，故其象佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>三以陽剛之才，正而且巽，上皆順之，復有援應。以是而升，如入無人之邑，孰御哉？</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><p>案：諸爻皆有吉利之佔，三獨無之。則“升虛邑”者，但言其勇於進而無所疑畏耳。方升之時，故無兇咎之辭，然終不如二五之中、初四之順也。九三過剛，與柔以時升之義反，故其辭非盡善。</p><p>象曰：升虛邑，無所疑也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>入無人之邑，其進無疑阻也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>蘇氏軾曰：九三以陽用陽，其升也果矣，故曰升虛邑，無所疑也。不言吉者，其為禍福未可知也，存乎其人而已。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>幹四曰“或之者疑之也”，故無咎。果於進而無所疑，可乎？蘇氏之說善矣。</p><p>六四：王用亨於岐山，吉無咎</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>義見隨卦。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四柔順之才，上順君之升，下順下之進，已則止其所焉。以陰居柔，陰而在下，止其所也。昔者文王之居岐山之下，上順天子而欲致之有道，下順天下之賢而使之升進，已則柔順謙恭，不出其位。至徳如此，周之王業用是而亨也。四能如是，則亨而吉且無咎矣。四之才固自善矣，復有無咎之辭何也？曰：四之才雖善，而其位當戒也。居近君之位，在升之時，不可復升，升則兇咎可知。故云如文王則吉而無咎也。然處大臣之位，不得無事於升，當上升其君之道，下昇天下之賢，已則止其分焉。分雖當止，而徳則當升也，道則當亨也。盡斯道者，其唯文王乎？</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><p>案：卦義柔以時升，六四初交上體，又位在巽坤之閒，有南征之象，迫近尊位，有見大人之義，是爻之合於卦義者也。在己者用之以見大人則吉，為大人者用之以享神明則宜。與隨上之義同，皆言“王用此人以享于山川”也。不曰“西山”而曰“岐山”，避《彖辭》“南征”之文。先儒或言岐山在周之西南。</p><p>象曰：王用亨於岐山，順事也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>以順而升，登祭于山之象。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>四居近君之位，而當升時，得吉而無咎者，以其有順德也。以柔居坤，順之至也。文王之亨於岐山，亦以順時而已。上順於上，下順乎下，已順處其義，故云順事也。案：用賢以享於神明，是順神明之心而事之者也。</p><p>六五：貞吉升階</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以陰居陽，當升而居尊位，必能正固，則可以得吉而升階矣。階，升之易者。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>五以下有剛中之應，故能居尊位而吉。然質本陰柔，必守貞固乃得其吉也。若不能貞固，則信賢不篤，任賢不終，安能吉也？階，所由而升也。任剛中之賢輔之而升，猶登進自階，言有由而易也。指言九二正應，然在下之賢皆用升之階也。能用賢，則彚升矣。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>李氏元量曰 ：貞吉升階，升而有序，故以階言之，謂賓主以揖遜而升者也。</p></li><li><p>王氏宗傳曰 ：《彖傳》言“柔以時升”，蓋謂五也。</p></li><li><p>熊氏良輔曰 ：以順而升，如歷階然。案：升至五而極，居坤地之中，亦有南征之象焉，乃卦之主也。不取君象，但為臣位之極者，與晉、漸之五同也。升階須從李氏、熊氏之說，蓋古者賓主三揖三讓而後升階，將上堂矣而猶退遜如此，以況君子始終之進以禮者也。升、晉之所以必貴於柔順者，以此。升階之戒不在貞字之外，乃發明貞吉之意爾。</p></li></ul><p>象曰：貞吉升階，大得志也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>倚任賢才而能貞固，如是而升，可以致天下之大治，其志可大得也。君道之升，患無賢才之助爾，有助則猶自階而升也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>何氏楷曰：即彖所謂有慶志行者也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>自初而升至此而升極矣，故初曰“上合志”，此曰“大得志”。</p><p>上六：冥升，利於不息之貞</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>以陰居升極，昏冥不已者也。佔者遇此無適而利，但可反其不已於外之心，施之於不息之正而已。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>六以陰居升之極，昏冥於升，知進而不知止者也，其為不明甚矣。然求升不已之心，有時而用於貞正而當不息之事，則為宜矣。君子於貞正之徳，終日乾乾，自強不息。如上六不已之心用之於此，則利也。以小人貪求無已之心移於進徳，則何善如之？</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>石氏介曰 ：已在升極，是昧於升進之理。若能知時消息，但自消退不更求進，乃利也。</p></li><li><p>徐氏之祥曰 ：豫上樂極，故冥豫；升上進極，故冥升。案：冥升與晉其角之義同，皆進而不能退者也。以其剛也，故曰角；以其柔也，故曰冥。利於不息之貞，其戒亦與“維用伐邑”之義同，皆勤於自治，不敢以盛滿自居者也。以其剛也，故曰伐邑；以其柔也，故曰不息之貞。</p></li></ul><p>象曰：冥升在上，消不富也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>昏冥於升極上而不知己，唯有消亡，豈復有加益也？不富，無復增益也。升既極，則有退而無進也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏瑗曰：上六既不達存亡之幾，以至於上位，固當消虛自損，不為尊大以自至於富盛也。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>胡氏之說善矣。然不曰“不息之貞，消不富也”，而曰“冥升在上”，者以在上明其位勢之滿盛，故當以自消損為貞也。</p>',114)])])}const m=e(i,[["render",n]]);export{b as __pageData,m as default};
